-- BOQ -> quotation phase 1. Run after supabase-boq-migration.sql.
create table if not exists public.price_list (
 id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id), sku text not null, name text not null, product_family text not null, material text, standard text, size_mm numeric, grade text, unit text not null default 'm', pipe_length_m numeric, rate numeric(14,2) not null, gst_percent numeric(5,2) not null default 18, hsn_code text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, sku));
create index if not exists idx_price_list_user_family_size on public.price_list(user_id, product_family, size_mm);
create table if not exists public.quotations (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id), boq_document_id bigint references public.boq_documents(id), quote_number text not null, customer_name text, customer_gstin text, status text not null default 'draft', validity_days int default 30, terms text, notes text, subtotal numeric(16,2), gst_total numeric(16,2), grand_total numeric(16,2), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, quote_number));
create table if not exists public.quotation_items (id bigint generated by default as identity primary key, quotation_id bigint not null references public.quotations(id) on delete cascade, user_id uuid not null references auth.users(id), boq_row_no bigint, boq_sno text, boq_description text, boq_qty numeric, boq_unit text, boq_reference_rate numeric, price_list_id bigint references public.price_list(id), match_status text, match_confidence numeric, qty numeric(16,3), unit text, rate numeric(14,2), gst_percent numeric(5,2), amount numeric(16,2), included boolean not null default true, is_suggested_accessory boolean not null default false, notes text);
create table if not exists public.quotation_counters (user_id uuid not null references auth.users(id), fiscal_year text not null, last_number int not null default 0, primary key(user_id, fiscal_year));
alter table public.price_list enable row level security; alter table public.quotations enable row level security; alter table public.quotation_items enable row level security; alter table public.quotation_counters enable row level security;
create or replace function public.next_quote_number(p_user_id uuid, p_fiscal_year text) returns integer language plpgsql security definer set search_path = public as $$ declare n integer; begin insert into quotation_counters(user_id, fiscal_year, last_number) values(p_user_id,p_fiscal_year,1) on conflict(user_id,fiscal_year) do update set last_number=quotation_counters.last_number+1 returning last_number into n; return n; end; $$;
revoke all on function public.next_quote_number(uuid, text) from public, anon, authenticated;
grant execute on function public.next_quote_number(uuid, text) to service_role;
notify pgrst, 'reload schema';
